SELECT n.nspname::text AS table_schema, c.relname::text AS table_name, a.attname::text AS column_name, format_type(a.atttypid,a.atttypmod)::text AS data_type, a.attnotnull AS not_null, c.relkind::text AS relation_kind FROM pg_catalog.pg_attribute a JOIN pg_catalog.pg_class c ON c.oid=a.attrelid JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','zc_private') AND c.relkind IN ('r','p','v','m') AND a.attnum > 0 AND NOT a.attisdropped
